import{$ as e,A as t,B as n,V as r}from"./chunks/framework.DrAJjmzW.js";var i=JSON.parse(`{"title":"What Are Tweaks?","description":"","frontmatter":{"title":"What Are Tweaks?"},"headers":[],"relativePath":"tweaks/what-are-tweaks.md","filePath":"tweaks/what-are-tweaks.md","lastUpdated":1793325070000}`),a={name:`tweaks/what-are-tweaks.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="what-are-tweaks" tabindex="-1">What Are Tweaks? <a class="header-anchor" href="#what-are-tweaks" aria-label="Permalink to “What Are Tweaks?”">​</a></h1><p>Tweaks are small, targeted changes to Windows settings, registry keys, or system services that modify how your PC behaves. In Sparkle, each tweak is a self-contained PowerShell script that applies a specific optimization or customization.</p><hr><h2 id="how-tweaks-work" tabindex="-1">How Tweaks Work <a class="header-anchor" href="#how-tweaks-work" aria-label="Permalink to “How Tweaks Work”">​</a></h2><p>Each tweak follows a simple structure:</p><ol><li><strong>A metadata file</strong> (<code>meta.json</code>) defines the tweak&#39;s name, description, category, risk level, and other properties.</li><li><strong>An apply script</strong> (<code>apply.ps1</code>) contains the PowerShell commands that make the change.</li><li><strong>An optional unapply script</strong> (<code>unapply.ps1</code>) reverses the change if the tweak is reversible.</li></ol><p>When you toggle a tweak on in Sparkle, it runs the <code>apply.ps1</code> script. When you toggle it off, it runs <code>unapply.ps1</code>.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Some tweaks don&#39;t have an unapply script. These show an &quot;Apply&quot; button instead of a toggle, since the change can&#39;t be automatically reversed.</p></div><hr><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to “Categories”">​</a></h2><p>Tweaks are grouped into categories so you can quickly find what you need:</p><table tabindex="0"><thead><tr><th>Category</th><th>What it covers</th></tr></thead><tbody><tr><td><strong>General</strong></td><td>Broad system tweaks and common settings.</td></tr><tr><td><strong>Appearance</strong></td><td>Visual changes like dark mode, taskbar layout, and clock format.</td></tr><tr><td><strong>Performance</strong></td><td>System optimizations that improve speed and responsiveness.</td></tr><tr><td><strong>Privacy</strong></td><td>Disabling telemetry, tracking, and data collection.</td></tr><tr><td><strong>Gaming</strong></td><td>Optimizations for FPS, game services, and GPU settings.</td></tr><tr><td><strong>Network</strong></td><td>TCP/IP tuning, DNS, and network latency improvements.</td></tr><tr><td><strong>GPU</strong></td><td>Graphics driver and hardware-accelerated scheduling settings.</td></tr></tbody></table><hr><h2 id="risk-levels-sparkle-2-16-0-required" tabindex="-1">Risk Levels <span style="color:#ff9800;">(Sparkle 2.16.0+ Required)</span> <a class="header-anchor" href="#risk-levels-sparkle-2-16-0-required" aria-label="Permalink to “Risk Levels (Sparkle 2.16.0+  Required)”">​</a></h2><p>Every tweak has a risk level so you know what to expect:</p><table tabindex="0"><thead><tr><th>Risk</th><th>Icon</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Safe</strong></td><td>Green</td><td>Low risk. These changes are unlikely to cause problems. Most tweaks fall into this category.</td></tr><tr><td><strong>Caution</strong></td><td>Yellow</td><td>May affect system behavior or certain apps. Review the tweak description before applying.</td></tr><tr><td><strong>Risky</strong></td><td>Red</td><td>Can significantly change system behavior. Apply with care and create a restore point first.</td></tr></tbody></table><hr><h2 id="safety-features" tabindex="-1">Safety Features <a class="header-anchor" href="#safety-features" aria-label="Permalink to “Safety Features”">​</a></h2><p>Sparkle provides several safeguards when using tweaks:</p><ul><li><strong>System Restore Points</strong> - Always create a restore point before applying tweaks. Sparkle supports this on the home page.</li><li><strong>Reversible Changes</strong> - Most tweaks can be toggled off to undo the change.</li><li><strong>Modal Warnings</strong> - Some tweaks show a confirmation dialog before applying, explaining what will change.</li><li><strong>Warning Icons</strong> - Tweaks with known side effects display a warning icon in the UI.</li></ul><hr><h2 id="reapplying-tweaks-sparkle-2-18-0-required" tabindex="-1">Reapplying Tweaks <span style="color:#ff9800;">(Sparkle 2.18.0+ Required)</span> <a class="header-anchor" href="#reapplying-tweaks-sparkle-2-18-0-required" aria-label="Permalink to “Reapplying Tweaks (Sparkle 2.18.0+  Required)”">​</a></h2><p>After applying a tweak, you can force it to reapply at any time:</p><ol><li>Find the tweak in the Tweaks page (it shows a toggle in the on position)</li><li><strong>Hold the Alt key</strong> and the &quot;Reapply&quot; button will appear</li><li>Click &quot;Reapply&quot; to run the tweak&#39;s apply script again</li></ol><p>This is useful if you&#39;ve modified system settings manually and want the tweak to reapply its changes, or if a tweak didn&#39;t apply correctly the first time.</p><hr><h2 id="browsing-tweaks" tabindex="-1">Browsing Tweaks <a class="header-anchor" href="#browsing-tweaks" aria-label="Permalink to “Browsing Tweaks”">​</a></h2><p>You can explore all available tweaks in two ways:</p><ul><li><strong>In the app</strong> - Open the Tweaks page to browse, search, and filter by category.</li><li><strong>In the docs</strong> - See the <a href="/tweaks/">All Tweaks</a> page for a full list with detailed descriptions and related links.</li></ul><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Look for the <span style="color:var(--md-primary-fg-color);">★ Recommended</span> icon in the app. These are tweaks that are generally safe and beneficial for most users.</p></div><hr><h2 id="creating-your-own-tweaks" tabindex="-1">Creating Your Own Tweaks <a class="header-anchor" href="#creating-your-own-tweaks" aria-label="Permalink to “Creating Your Own Tweaks”">​</a></h2><p>Sparkle&#39;s tweak system is open and extensible. If you want to create a custom tweak, see the <a href="/creating-tweaks">Creating Tweaks</a> guide for the full specification and directory structure.</p>`,33)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};